-- ADA-ELM schema for MySQL / MariaDB, Alembic head: 0005_checklist_tagging. Generated by generate_sql.sh, do not edit by hand.
-- Run INSIDE the existing database:   mysql -u <admin> -p proflow_uat < 01_elm_schema.sql
-- Creates only elm_* tables (and elm_alembic_version). Legacy PMS tables are not read, changed or dropped.
-- Preferred alternative that also handles later upgrades: python -m app.dbsetup  (see Docs/RUNNING.md).
SET NAMES utf8mb4;
SET default_storage_engine = InnoDB;

CREATE TABLE elm_alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT elm_alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_elm_baseline

CREATE TABLE elm_audit_chain_head (
    id INTEGER NOT NULL AUTO_INCREMENT, 
    last_hash VARCHAR(64) NOT NULL, 
    last_seq BIGINT NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE elm_document_types (
    code VARCHAR(30) NOT NULL, 
    name VARCHAR(150) NOT NULL, 
    category VARCHAR(30) NOT NULL, 
    description LONGTEXT, 
    numbering_pattern VARCHAR(200) NOT NULL, 
    revision_scheme VARCHAR(20) NOT NULL, 
    allowed_extensions VARCHAR(300) NOT NULL, 
    default_template VARCHAR(20), 
    requires_signature BOOL NOT NULL, 
    applicable_levels VARCHAR(300), 
    icon VARCHAR(40), 
    color VARCHAR(20), 
    active BOOL NOT NULL, 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (code)
);

CREATE TABLE elm_legacy_audit_records (
    source_system VARCHAR(40) NOT NULL, 
    source_table VARCHAR(80) NOT NULL, 
    source_id VARCHAR(80) NOT NULL, 
    at DATETIME(6), 
    username VARCHAR(250), 
    action VARCHAR(100), 
    entity_type VARCHAR(100), 
    entity_id VARCHAR(100), 
    details LONGTEXT, 
    id CHAR(32) NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT uq_legacy_audit UNIQUE (source_system, source_table, source_id)
);

CREATE INDEX ix_elm_legacy_audit_records_at ON elm_legacy_audit_records (at);

CREATE TABLE elm_legacy_import_runs (
    source_system VARCHAR(40) NOT NULL, 
    source_database VARCHAR(120), 
    bundle_sha256 VARCHAR(64) NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    report LONGTEXT, 
    started_at DATETIME(6) NOT NULL, 
    finished_at DATETIME(6), 
    id CHAR(32) NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE elm_number_sequences (
    `key` VARCHAR(200) NOT NULL, 
    next_value INTEGER NOT NULL, 
    id CHAR(32) NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (`key`)
);

CREATE TABLE elm_org_units (
    parent_id CHAR(32), 
    code VARCHAR(40) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    unit_type VARCHAR(40) NOT NULL, 
    path VARCHAR(1000) NOT NULL, 
    description LONGTEXT, 
    is_oversight BOOL NOT NULL, 
    active BOOL NOT NULL, 
    sort_order INTEGER NOT NULL, 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(parent_id) REFERENCES elm_org_units (id), 
    UNIQUE (code)
);

CREATE INDEX ix_elm_org_units_parent_id ON elm_org_units (parent_id);

CREATE INDEX ix_elm_org_units_path ON elm_org_units (path);

CREATE TABLE elm_process_domains (
