);

CREATE INDEX ix_elm_legacy_import_map_run_id ON elm_legacy_import_map (run_id);

CREATE TABLE elm_projects (
    code VARCHAR(40) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    programme VARCHAR(120), 
    description LONGTEXT, 
    status VARCHAR(30) NOT NULL, 
    lead_org_unit_id CHAR(32), 
    start_date DATE, 
    end_date DATE, 
    color VARCHAR(20), 
    classification VARCHAR(40), 
