    CONSTRAINT uq_role_perm UNIQUE (role_id, permission)
);

CREATE INDEX ix_elm_role_permissions_role_id ON elm_role_permissions (role_id);

CREATE TABLE elm_users (
    username VARCHAR(80) NOT NULL, 
    full_name VARCHAR(200) NOT NULL, 
    email VARCHAR(200), 
    employee_no VARCHAR(40), 
    designation VARCHAR(120), 
    password_hash VARCHAR(255), 
    auth_source VARCHAR(20) NOT NULL, 
    is_active BOOL NOT NULL, 
    is_system_admin BOOL NOT NULL, 
    primary_org_unit_id CHAR(32), 
    failed_logins INTEGER NOT NULL, 
    locked_until DATETIME(6), 
    last_login_at DATETIME(6), 
    preferences LONGTEXT, 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(primary_org_unit_id) REFERENCES elm_org_units (id), 
    UNIQUE (employee_no), 
    UNIQUE (username)
);

CREATE TABLE elm_audit_events (
    seq BIGINT NOT NULL AUTO_INCREMENT, 
    id CHAR(32) NOT NULL, 
    at DATETIME(6) NOT NULL, 
    actor_id CHAR(32), 
    on_behalf_of_id CHAR(32), 
    action VARCHAR(80) NOT NULL, 
    entity_type VARCHAR(60) NOT NULL, 
    entity_id VARCHAR(64), 
    summary VARCHAR(500) NOT NULL, 
    data LONGTEXT, 
    ip VARCHAR(64), 
    request_id VARCHAR(64), 
    outcome VARCHAR(20) NOT NULL, 
    prev_hash VARCHAR(64) NOT NULL, 
    hash VARCHAR(64) NOT NULL, 
    PRIMARY KEY (seq), 
    FOREIGN KEY(actor_id) REFERENCES elm_users (id), 
    FOREIGN KEY(on_behalf_of_id) REFERENCES elm_users (id), 
    UNIQUE (id)
);

CREATE INDEX ix_elm_audit_events_action ON elm_audit_events (action);

CREATE INDEX ix_elm_audit_events_actor_id ON elm_audit_events (actor_id);

CREATE INDEX ix_elm_audit_events_at ON elm_audit_events (at);

