    domain_id CHAR(32), 
    lead_org_unit_id CHAR(32), 
    technical_owner_id CHAR(32), 
    lifecycle_phase VARCHAR(40) NOT NULL, 
    status VARCHAR(30) NOT NULL, 
    path VARCHAR(2000) NOT NULL, 
    sort_order INTEGER NOT NULL, 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    version INTEGER NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(domain_id) REFERENCES elm_process_domains (id), 
    FOREIGN KEY(lead_org_unit_id) REFERENCES elm_org_units (id), 
    FOREIGN KEY(level_id) REFERENCES elm_hierarchy_levels (id), 
    FOREIGN KEY(parent_id) REFERENCES elm_engineering_items (id), 
    FOREIGN KEY(project_id) REFERENCES elm_projects (id), 
    FOREIGN KEY(technical_owner_id) REFERENCES elm_users (id), 
    CONSTRAINT uq_item_code UNIQUE (project_id, code)
