CREATE TABLE elm_documents (
    number VARCHAR(120) NOT NULL, 
    title VARCHAR(400) NOT NULL, 
    description LONGTEXT, 
    type_id CHAR(32) NOT NULL, 
    project_id CHAR(32), 
    item_id CHAR(32), 
    domain_id CHAR(32), 
    owner_org_unit_id CHAR(32), 
    originating_org_unit_id CHAR(32), 
    owner_id CHAR(32) NOT NULL, 
    classification VARCHAR(40) NOT NULL, 
    status VARCHAR(30) NOT NULL, 
    current_revision_id CHAR(32), 
    released_revision_id CHAR(32), 
    keywords VARCHAR(500), 
    due_date DATETIME(6), 
    external_ref VARCHAR(200), 
    legacy_ref VARCHAR(100), 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    version INTEGER NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(domain_id) REFERENCES elm_process_domains (id), 
    FOREIGN KEY(item_id) REFERENCES elm_engineering_items (id), 
    FOREIGN KEY(originating_org_unit_id) REFERENCES elm_org_units (id), 
    FOREIGN KEY(owner_id) REFERENCES elm_users (id), 
    FOREIGN KEY(owner_org_unit_id) REFERENCES elm_org_units (id), 
    FOREIGN KEY(project_id) REFERENCES elm_projects (id), 
    FOREIGN KEY(type_id) REFERENCES elm_document_types (id), 
    UNIQUE (number)
);

