    FOREIGN KEY(run_id) REFERENCES elm_test_runs (id), 
    CONSTRAINT uq_run_case UNIQUE (run_id, case_id)
);

CREATE INDEX ix_elm_test_run_cases_case_id ON elm_test_run_cases (case_id);

CREATE INDEX ix_elm_test_run_cases_run_id ON elm_test_run_cases (run_id);

CREATE TABLE elm_test_suite_cases (
    suite_id CHAR(32) NOT NULL, 
    case_id CHAR(32) NOT NULL, 
