    PRIMARY KEY (id), 
    FOREIGN KEY(case_id) REFERENCES elm_test_cases (id), 
    FOREIGN KEY(suite_id) REFERENCES elm_test_suites (id), 
    CONSTRAINT uq_suite_case UNIQUE (suite_id, case_id)
);

CREATE INDEX ix_elm_test_suite_cases_case_id ON elm_test_suite_cases (case_id);

CREATE INDEX ix_elm_test_suite_cases_suite_id ON elm_test_suite_cases (suite_id);

CREATE TABLE elm_defects (
    project_id CHAR(32) NOT NULL, 
    item_id CHAR(32), 
    `key` VARCHAR(60) NOT NULL, 
    title VARCHAR(300) NOT NULL, 
    description LONGTEXT, 
    severity VARCHAR(20) NOT NULL, 
    priority VARCHAR(10) NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    assignee_id CHAR(32), 
    reporter_id CHAR(32), 
    fixed_by_id CHAR(32), 
    found_in_build VARCHAR(120), 
    fixed_in_build VARCHAR(120), 
    work_item_id CHAR(32), 
    resolution LONGTEXT, 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    version INTEGER NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(assignee_id) REFERENCES elm_users (id), 
    FOREIGN KEY(fixed_by_id) REFERENCES elm_users (id), 
    FOREIGN KEY(item_id) REFERENCES elm_engineering_items (id), 
    FOREIGN KEY(project_id) REFERENCES elm_projects (id), 
    FOREIGN KEY(reporter_id) REFERENCES elm_users (id), 
    FOREIGN KEY(work_item_id) REFERENCES elm_work_items (id), 
    UNIQUE (`key`)
);

CREATE INDEX ix_elm_defects_assignee_id ON elm_defects (assignee_id);

CREATE INDEX ix_elm_defects_project_id ON elm_defects (project_id);

CREATE INDEX ix_elm_defects_status ON elm_defects (status);

CREATE TABLE elm_test_executions (
    run_case_id CHAR(32) NOT NULL, 
    result VARCHAR(20) NOT NULL, 
    actual_result LONGTEXT, 
    failure_cause VARCHAR(40), 
    defect_id CHAR(32), 
    is_retest BOOL NOT NULL, 
    tester_id CHAR(32), 
    source VARCHAR(20) NOT NULL, 
    external_result_id VARCHAR(200), 
    duration_seconds FLOAT, 
    executed_at DATETIME(6) NOT NULL, 
    notes LONGTEXT, 
    id CHAR(32) NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(defect_id) REFERENCES elm_defects (id), 
    FOREIGN KEY(run_case_id) REFERENCES elm_test_run_cases (id), 
    FOREIGN KEY(tester_id) REFERENCES elm_users (id), 
    UNIQUE (external_result_id)
);

CREATE INDEX ix_elm_test_executions_defect_id ON elm_test_executions (defect_id);

CREATE INDEX ix_elm_test_executions_executed_at ON elm_test_executions (executed_at);

CREATE INDEX ix_elm_test_executions_run_case_id ON elm_test_executions (run_case_id);

CREATE TABLE elm_test_evidence (
    execution_id CHAR(32) NOT NULL, 
    file_id CHAR(32) NOT NULL, 
    kind VARCHAR(30) NOT NULL, 
    uploaded_at DATETIME(6) NOT NULL, 
    uploaded_by_id CHAR(32), 
    id CHAR(32) NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(execution_id) REFERENCES elm_test_executions (id), 
    FOREIGN KEY(file_id) REFERENCES elm_file_objects (id), 
    FOREIGN KEY(uploaded_by_id) REFERENCES elm_users (id)
);

CREATE INDEX ix_elm_test_evidence_execution_id ON elm_test_evidence (execution_id);

