CREATE TABLE elm_deploy_environments (
    project_id CHAR(32) NOT NULL, 
    code VARCHAR(30) NOT NULL, 
    name VARCHAR(150) NOT NULL, 
    description LONGTEXT, 
    sort_order INTEGER NOT NULL, 
    active BOOL NOT NULL, 
    config LONGTEXT NOT NULL, 
    config_sha256 VARCHAR(64) NOT NULL, 
    config_status VARCHAR(20) NOT NULL, 
    config_approved_sha256 VARCHAR(64), 
    config_approved_by_id CHAR(32), 
    config_approved_at DATETIME(6), 
    config_changed_by_id CHAR(32), 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    version INTEGER NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(config_approved_by_id) REFERENCES elm_users (id), 
    FOREIGN KEY(config_changed_by_id) REFERENCES elm_users (id), 
    FOREIGN KEY(project_id) REFERENCES elm_projects (id), 
    CONSTRAINT uq_deploy_env_code UNIQUE (project_id, code)
);

CREATE INDEX ix_elm_deploy_environments_project_id ON elm_deploy_environments (project_id);

CREATE TABLE elm_deployments (
    project_id CHAR(32) NOT NULL, 
    environment_id CHAR(32) NOT NULL, 
    `key` VARCHAR(60) NOT NULL, 
    title VARCHAR(300) NOT NULL, 
    version_label VARCHAR(120) NOT NULL, 
    repository_id CHAR(32), 
    git_ref VARCHAR(255), 
    commit_sha VARCHAR(64), 
    release_notes LONGTEXT, 
    test_run_id CHAR(32), 
    checklist LONGTEXT, 
    status VARCHAR(20) NOT NULL, 
    content_sha256 VARCHAR(64) NOT NULL, 
    rollback_of_id CHAR(32), 
    requested_by_id CHAR(32), 
    deployed_at DATETIME(6), 
    status_reason VARCHAR(1000), 
    id CHAR(32) NOT NULL, 
    created_at DATETIME(6) NOT NULL, 
    updated_at DATETIME(6) NOT NULL, 
    version INTEGER NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(environment_id) REFERENCES elm_deploy_environments (id), 
    FOREIGN KEY(project_id) REFERENCES elm_projects (id), 
    FOREIGN KEY(repository_id) REFERENCES elm_scm_repositories (id), 
    FOREIGN KEY(requested_by_id) REFERENCES elm_users (id), 
    FOREIGN KEY(rollback_of_id) REFERENCES elm_deployments (id), 
    FOREIGN KEY(test_run_id) REFERENCES elm_test_runs (id), 
    UNIQUE (`key`)
);

CREATE INDEX ix_elm_deployments_environment_id ON elm_deployments (environment_id);

CREATE INDEX ix_elm_deployments_project_id ON elm_deployments (project_id);

CREATE INDEX ix_elm_deployments_status ON elm_deployments (status);

